function Show-SplashScreen {
    param([scriptblock]$OnFinished)

    $reader = New-Object System.Xml.XmlNodeReader $splashXaml
    $splash = [Windows.Markup.XamlReader]::Load($reader)

    $script:ProgressPanel   = $splash.FindName("ProgressPanel")
    $script:LoadBarFill     = $splash.FindName("LoadBarFill")
    $script:TxtLoadPct      = $splash.FindName("TxtLoadPct")
    $script:TxtLoadStatus   = $splash.FindName("TxtLoadStatus")
    $script:BtnStart        = $splash.FindName("BtnStart")
    $script:TxtHint         = $splash.FindName("TxtHint")
    $TitleBar               = $splash.FindName("TitleBar")
    $BtnMin                 = $splash.FindName("BtnMin")
    $BtnClose               = $splash.FindName("BtnClose")
    $BgImage                = $splash.FindName("BgImage")
    if ($BgImage -and $script:BgBitmap) {
        $BgImage.Source = $script:BgBitmap
    }

    $script:splash          = $splash
    $script:OnFinished      = $OnFinished
    $script:splashMaxWidth  = 480
    $script:splashSteps     = @(
        @{Pct = 15;  Msg = "Booting interface..."},
        @{Pct = 32;  Msg = "Linking system telemetry..."},
        @{Pct = 50;  Msg = "Rendering Savage Tool shell..."},
        @{Pct = 68;  Msg = "Reading hardware profile..."},
        @{Pct = 85;  Msg = "Calibrating HUD modules..."},
        @{Pct = 100; Msg = "Ready."}
    )

    if ($TitleBar) { $TitleBar.Add_MouseLeftButtonDown({ $script:splash.DragMove() }) }
    if ($BtnMin)   { $BtnMin.Add_Click({ $script:splash.WindowState = 'Minimized' }) }
    if ($BtnClose) { $BtnClose.Add_Click({ $script:splash.Close() }) }

    $script:splashStepIndex = 0
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(160)
    $script:timer = $timer

    $timer.Add_Tick({
        try {
            if ($script:splashStepIndex -ge $script:splashSteps.Count) {
                $script:timer.Stop()
                Start-Sleep -Milliseconds 250
                $script:splash.Close()
                if ($script:OnFinished) { & $script:OnFinished }
                return
            }

            $step = $script:splashSteps[$script:splashStepIndex]
            if ($script:LoadBarFill)   { $script:LoadBarFill.Width  = [double]$script:splashMaxWidth * ($step.Pct / 100.0) }
            if ($script:TxtLoadPct)    { $script:TxtLoadPct.Text    = "$($step.Pct)%" }
            if ($script:TxtLoadStatus) { $script:TxtLoadStatus.Text = $step.Msg }

            $script:splashStepIndex++
        } catch {
            $script:timer.Stop()
            [System.Windows.MessageBox]::Show(
                "Splash screen failed to load the dashboard:`n$($_.Exception.Message)",
                "Savage Tool - Error"
            ) | Out-Null
        }
    })

    $script:BtnStart.Add_Click({
        try {
            $script:BtnStart.IsEnabled = $false
            $script:BtnStart.Content = "LOADING..."
            if ($script:TxtHint)       { $script:TxtHint.Visibility       = [System.Windows.Visibility]::Collapsed }
            if ($script:ProgressPanel) { $script:ProgressPanel.Visibility = [System.Windows.Visibility]::Visible }
            $script:splashStepIndex = 0
            $script:timer.Start()
        } catch {
            [System.Windows.MessageBox]::Show(
                "Error starting dashboard: $($_.Exception.Message)",
                "Savage Tool Error"
            ) | Out-Null
        }
    })

    $splash.ShowDialog() | Out-Null
}

function Get-SafeValue {
    param([scriptblock]$Block, [string]$Fallback = "Unavailable")
    try {
        $result = & $Block
        if ([string]::IsNullOrWhiteSpace($result)) { return $Fallback }
        return $result
    } catch {
        return $Fallback
    }
}


