                                </Track.Thumb>
                                <Track.IncreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageDownCommand" Opacity="0" Focusable="False"/>
                                </Track.IncreaseRepeatButton>
                                <Track.DecreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageUpCommand" Opacity="0" Focusable="False"/>
                                </Track.DecreaseRepeatButton>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="ActionBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#F5F5F8"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Height" Value="46"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="16,0,0,0"/>
            <Setter Property="Background" Value="#1F1F24"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
            <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
            <Setter Property="RenderTransform">
                <Setter.Value>
                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                </Setter.Value>
            </Setter>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="10" Background="{TemplateBinding Background}"
                                BorderThickness="1" BorderBrush="#32323A">
                            <Border.Effect>
                                <DropShadowEffect x:Name="btnGlow" Color="#E5A93C" BlurRadius="0" ShadowDepth="0" Opacity="0"/>
                            </Border.Effect>
                            <Grid>
                                <Border x:Name="accentDot" Width="6" Height="6" CornerRadius="3"
                                        HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,16,0"
                                        Background="#E5A93C"/>
                                <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"
                                                   Margin="{TemplateBinding Padding}"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="border"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#E5A93C" Duration="0:0:0.15"/>
                                            <ColorAnimation Storyboard.TargetName="accentDot"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#121214" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                              Storyboard.TargetProperty="BlurRadius" To="14" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                              Storyboard.TargetProperty="Opacity" To="0.55" Duration="0:0:0.15"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="border"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#1F1F24" Duration="0:0:0.2"/>
                                            <ColorAnimation Storyboard.TargetName="accentDot"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#E5A93C" Duration="0:0:0.2"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                              Storyboard.TargetProperty="BlurRadius" To="0" Duration="0:0:0.2"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                              Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.2"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                                <Setter Property="Foreground" Value="#121214"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="AppBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#F5F5F8"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Height" Value="44"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="14,0,0,0"/>
            <Setter Property="Background" Value="#1F1F24"/>
            <Setter Property="Margin" Value="0,0,0,0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="9" Background="{TemplateBinding Background}"
                                BorderThickness="1" BorderBrush="#32323A">
                            <Grid>
                                <Border x:Name="accentDot" Width="6" Height="6" CornerRadius="3"
                                        HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,14,0"
                                        Background="#E5A93C"/>
                                <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"
                                                   Margin="{TemplateBinding Padding}"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#E5A93C"/>
                                <Setter TargetName="accentDot" Property="Background" Value="#121214"/>
                                <Setter TargetName="border" Property="BorderBrush" Value="#F5B94B"/>
                                <Setter Property="Foreground" Value="#121214"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="HwCard" TargetType="Border">
            <Setter Property="Background" Value="#18181C"/>
            <Setter Property="CornerRadius" Value="9"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="BorderBrush" Value="#2A2A30"/>
            <Setter Property="Padding" Value="10,8"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
        </Style>

        <Style x:Key="HwIconBox" TargetType="Border">
            <Setter Property="Width" Value="30"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="CornerRadius" Value="7"/>
            <Setter Property="Background" Value="#2C2316"/>
        </Style>

        <Style x:Key="HwLabel" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#8A8A94"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="9.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
        </Style>

        <Style x:Key="HwValue" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#F5F5F8"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="TextWrapping" Value="Wrap"/>
        </Style>

        <Style x:Key="RailIcon" TargetType="Border">
            <Setter Property="Width" Value="34"/>
            <Setter Property="Height" Value="34"/>
            <Setter Property="CornerRadius" Value="9"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Margin" Value="0,0,0,6"/>
        </Style>

        <Style x:Key="StartBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#E5A93C"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Height" Value="42"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Background" Value="#222228"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="10" Background="{TemplateBinding Background}"
                                BorderThickness="1.2" BorderBrush="#4A3C1A">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#E5A93C"/>
                                <Setter TargetName="border" Property="BorderBrush" Value="#F5B94B"/>
                                <Setter Property="Foreground" Value="#121214"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="CapBtn" TargetType="Button">
            <Setter Property="Width" Value="30"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="Foreground" Value="#C8C8D2"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="FontFamily" Value="Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="cb" CornerRadius="8" Background="{TemplateBinding Background}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="cb" Property="Background" Value="#2E2E36"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="GlassCard" TargetType="Border">
            <Setter Property="Background" Value="#E618181C"/>
            <Setter Property="CornerRadius" Value="16"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="BorderBrush" Value="#2A2A30"/>
            <Setter Property="Padding" Value="20"/>
        </Style>

        <Style x:Key="SpecLabel" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#E5A93C"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="10"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Margin" Value="0,9,0,2"/>
            <Setter Property="TextOptions.TextFormattingMode" Value="Display"/>
            <Setter Property="TextOptions.TextRenderingMode" Value="ClearType"/>
        </Style>
        <Style x:Key="SpecValue" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#F5F5F8"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="TextWrapping" Value="Wrap"/>
            <Setter Property="TextOptions.TextFormattingMode" Value="Display"/>
            <Setter Property="TextOptions.TextRenderingMode" Value="ClearType"/>
        </Style>
    </Window.Resources>

    <Grid>
        <Border CornerRadius="20" BorderThickness="0" Margin="-6">
            <Border.Background>
                <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                    <GradientStop Color="#5A4214" Offset="0"/>
                    <GradientStop Color="#E5A93C" Offset="0.5"/>
                    <GradientStop Color="#4A3C1A" Offset="1"/>
                </LinearGradientBrush>
            </Border.Background>
            <Border.Effect>
                <DropShadowEffect x:Name="OuterGlow" Color="#E5A93C" BlurRadius="26" ShadowDepth="0" Opacity="0.35"/>
            </Border.Effect>
        </Border>

    <Border CornerRadius="20" BorderThickness="1.4">
        <Border.BorderBrush>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                <GradientStop Color="#7A5C1E" Offset="0"/>
                <GradientStop Color="#E5A93C" Offset="0.5"/>
                <GradientStop Color="#F5B94B" Offset="1"/>
            </LinearGradientBrush>
        </Border.BorderBrush>
        <Border.Background>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                <GradientStop Color="#121214" Offset="0"/>
                <GradientStop Color="#161619" Offset="0.5"/>
                <GradientStop Color="#18181C" Offset="1"/>
            </LinearGradientBrush>
        </Border.Background>

        <Grid ClipToBounds="True">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
            </Grid.RowDefinitions>

            <!-- Background artwork -->
            <Image x:Name="BgImage" Grid.Row="0" Grid.RowSpan="3" Stretch="UniformToFill"
                   Opacity="0.35" IsHitTestVisible="False"/>
            <Border Grid.Row="0" Grid.RowSpan="3" IsHitTestVisible="False">
                <Border.Background>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                        <GradientStop Color="#121214" Offset="0"/>
                        <GradientStop Color="#8A121214" Offset="0.4"/>
                        <GradientStop Color="#121214" Offset="1"/>
                    </LinearGradientBrush>
                </Border.Background>
            </Border>

            <!-- nebula + stars backdrop -->
            <Canvas Grid.Row="0" Grid.RowSpan="3" IsHitTestVisible="False">
                <Ellipse Canvas.Left="-100" Canvas.Top="-70" Width="340" Height="340" Opacity="0.12">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#E5A93C" Offset="0"/>
                            <GradientStop Color="#121214" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="30"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="820" Canvas.Top="-40" Width="320" Height="320" Opacity="0.11">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#F5B94B" Offset="0"/>
                            <GradientStop Color="#121214" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="30"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="380" Canvas.Top="560" Width="360" Height="240" Opacity="0.10">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#B8860B" Offset="0"/>
                            <GradientStop Color="#121214" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="32"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="60"  Canvas.Top="130" Width="2" Height="2" Fill="#ffffff" Opacity="0.5"/>
                <Ellipse Canvas.Left="950" Canvas.Top="90"  Width="2" Height="2" Fill="#FFEFC4" Opacity="0.6"/>
                <Ellipse Canvas.Left="1020" Canvas.Top="260" Width="3" Height="3" Fill="#F5D07A" Opacity="0.55"/>
                <Ellipse Canvas.Left="40"  Canvas.Top="600" Width="2" Height="2" Fill="#FFFFFF" Opacity="0.5"/>
                <Ellipse Canvas.Left="1040" Canvas.Top="620" Width="2" Height="2" Fill="#F5B94B" Opacity="0.5"/>
            </Canvas>

            <!-- custom title bar -->
            <Grid x:Name="TitleBar" Grid.Row="0" Height="42" Background="Transparent">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock Grid.Column="0" Text="◈  SAVAGE TOOL — KERNELOS EDITION" Foreground="#E5A93C"
                           FontFamily="Segoe UI Semibold" FontSize="11" VerticalAlignment="Center" Margin="16,0,0,0"/>
                <TextBlock Grid.Column="1" Text="ADVANCED FIVEM &amp; SYSTEM OPTIMIZATION CONSOLE" Foreground="#8A8A94"
                           FontFamily="Consolas" FontSize="13" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                <StackPanel Grid.Column="2" Orientation="Horizontal" Margin="0,0,8,0">
                    <Button x:Name="BtnMin" Style="{StaticResource CapBtn}" Content="&#x2014;"/>
                    <Button x:Name="BtnClose" Style="{StaticResource CapBtn}" Content="&#x2715;"/>
                </StackPanel>
            </Grid>

            <!-- header -->
            <Grid Grid.Row="1" Margin="30,10,30,16">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Grid.Column="0">
                    <TextBlock Text="◈ SAVAGE TOOL" FontFamily="Segoe UI Black" FontSize="24">
                        <TextBlock.Foreground>
                            <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                                <GradientStop Color="#FFFFFF" Offset="0"/>
                                <GradientStop Color="#F5B94B" Offset="0.5"/>
                                <GradientStop Color="#E5A93C" Offset="1"/>
                            </LinearGradientBrush>
                        </TextBlock.Foreground>
                    </TextBlock>
                    <TextBlock Text="SYSTEM &amp; FIVEM OPTIMIZATION — KERNELOS PERFORMANCE ARCHITECTURE" Foreground="#8A8A94"
                               FontFamily="Consolas" FontSize="12.5" Margin="2,4,0,0"/>
                </StackPanel>
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">

                    <Border CornerRadius="16" BorderThickness="1" BorderBrush="#2A2A30"
                            Background="#18181C" Padding="14,7" VerticalAlignment="Center">
                        <StackPanel Orientation="Horizontal">
                            <Ellipse Width="9" Height="9" Fill="#00EBA0" Margin="0,0,8,0" VerticalAlignment="Center"
                                     RenderTransformOrigin="0.5,0.5">
                                <Ellipse.RenderTransform>
                                    <ScaleTransform x:Name="OnlineDotScale" ScaleX="1" ScaleY="1"/>
                                </Ellipse.RenderTransform>
                                <Ellipse.Effect><DropShadowEffect Color="#00EBA0" BlurRadius="10" ShadowDepth="0" Opacity="0.9"/></Ellipse.Effect>
                            </Ellipse>
                            <TextBlock Text="ONLINE" Foreground="#00EBA0" FontFamily="Consolas" FontSize="12" FontWeight="Bold" VerticalAlignment="Center"/>
                        </StackPanel>
                    </Border>
                </StackPanel>
            </Grid>

            <!-- body: ICON RAIL | PROFILE+HARDWARE sidebar | MAIN (commands grid + tweaks/log) -->
            <Grid Grid.Row="2" Margin="30,0,30,26">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="62"/>
                    <ColumnDefinition Width="14"/>
                    <ColumnDefinition Width="230"/>
                    <ColumnDefinition Width="16"/>
                    <ColumnDefinition/>
                </Grid.ColumnDefinitions>

                <!-- ICON RAIL (decorative app-shell icon strip) -->
                <Border Grid.Column="0" Style="{StaticResource GlassCard}" Padding="8,16">
                    <StackPanel HorizontalAlignment="Center">
                        <Border Style="{StaticResource RailIcon}" Background="#E5A93C">
                            <TextBlock Text="&#x25C8;" Foreground="#121214" FontSize="16" FontWeight="Bold"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x2699;" Foreground="#8A8A94" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x1F310;" Foreground="#8A8A94" FontFamily="Segoe UI Emoji" FontSize="14"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x2328;" Foreground="#8A8A94" FontFamily="Segoe UI Emoji" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}" Margin="0,90,0,0">
                            <TextBlock Text="&#x1F464;" Foreground="#8A8A94" FontFamily="Segoe UI Emoji" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                    </StackPanel>
                </Border>

                <!-- SIDEBAR: profile card + hardware cards -->
                <Border Grid.Column="2" Style="{StaticResource GlassCard}" Padding="14">
                    <Grid>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="*"/>
                            <RowDefinition Height="Auto"/>
                        </Grid.RowDefinitions>

                        <!-- profile -->
                        <StackPanel Grid.Row="0" HorizontalAlignment="Center" Margin="0,4,0,14">
                            <Border Width="54" Height="54" CornerRadius="27" Background="#121214"
                                     BorderThickness="1.8" BorderBrush="#E5A93C" Margin="0,0,0,8">
                                <Grid>
                                    <TextBlock x:Name="AvatarFallbackIcon" Text="&#x1F464;" FontFamily="Segoe UI Emoji" FontSize="22"
                                               HorizontalAlignment="Center" VerticalAlignment="Center" Foreground="#E5A93C"/>
                                    <Ellipse x:Name="AvatarImage" Width="50.8" Height="50.8" Visibility="Collapsed"
                                             HorizontalAlignment="Center" VerticalAlignment="Center">
                                        <Ellipse.Fill>
                                            <ImageBrush x:Name="AvatarImageBrush" Stretch="UniformToFill"/>
                                        </Ellipse.Fill>
                                    </Ellipse>
                                </Grid>
                            </Border>
                            <TextBlock x:Name="TxtUserName" Text="Administrator" Foreground="#F5F5F8"
                                       FontFamily="Consolas" FontSize="12" FontWeight="Bold" HorizontalAlignment="Center"/>
                            <TextBlock x:Name="TxtComputerName" Text="-" Foreground="#8A8A94"
                                       FontFamily="Consolas" FontSize="10" HorizontalAlignment="Center" Margin="0,2,0,0"/>
                        </StackPanel>

                        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
                            <StackPanel>
                                <TextBlock Text="◈ HARDWARE" Foreground="#E5A93C" FontFamily="Consolas"
                                           FontSize="9.5" FontWeight="Bold" Margin="2,0,0,8"/>

                                <Border Style="{StaticResource HwCard}">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition/>
                                        </Grid.ColumnDefinitions>
                                        <Border Style="{StaticResource HwIconBox}">
                                            <Viewbox Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                <Canvas Width="24" Height="24">
                                                    <Rectangle Canvas.Left="3" Canvas.Top="4" Width="18" Height="12" RadiusX="2" RadiusY="2" Stroke="#E5A93C" StrokeThickness="1.8" Fill="Transparent"/>
                                                    <Line X1="9" Y1="20" X2="15" Y2="20" Stroke="#E5A93C" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="12" Y1="16" X2="12" Y2="20" Stroke="#E5A93C" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                </Canvas>
                                            </Viewbox>
                                        </Border>
                                        <StackPanel Grid.Column="1" Margin="10,0,0,0" VerticalAlignment="Center">
                                            <TextBlock Text="OS" Style="{StaticResource HwLabel}"/>
                                            <TextBlock x:Name="TxtOs" Text="-" Style="{StaticResource HwValue}"/>
                                        </StackPanel>
                                    </Grid>
                                </Border>

                                <Border Style="{StaticResource HwCard}">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition/>
                                        </Grid.ColumnDefinitions>
                                        <Border Style="{StaticResource HwIconBox}">
                                            <Viewbox Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                <Canvas Width="24" Height="24">
                                                    <Rectangle Canvas.Left="6" Canvas.Top="6" Width="12" Height="12" RadiusX="1.5" RadiusY="1.5" Stroke="#E5A93C" StrokeThickness="1.8" Fill="Transparent"/>
                                                    <Rectangle Canvas.Left="9.5" Canvas.Top="9.5" Width="5" Height="5" Stroke="#E5A93C" StrokeThickness="1.3" Fill="Transparent"/>
                                                    <Line X1="9" Y1="2" X2="9" Y2="6" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="15" Y1="2" X2="15" Y2="6" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="9" Y1="18" X2="9" Y2="22" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="15" Y1="18" X2="15" Y2="22" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="2" Y1="9" X2="6" Y2="9" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="2" Y1="15" X2="6" Y2="15" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="18" Y1="9" X2="22" Y2="9" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="18" Y1="15" X2="22" Y2="15" Stroke="#E5A93C" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                </Canvas>
                                            </Viewbox>
                                        </Border>
                                        <StackPanel Grid.Column="1" Margin="10,0,0,0" VerticalAlignment="Center">
                                            <TextBlock Text="CPU" Style="{StaticResource HwLabel}"/>
                                            <TextBlock x:Name="TxtCpu" Text="-" Style="{StaticResource HwValue}"/>
                                        </StackPanel>
                                    </Grid>
                                </Border>

                                <Border Style="{StaticResource HwCard}">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition/>
                                        </Grid.ColumnDefinitions>
                                        <Border Style="{StaticResource HwIconBox}">
                                            <Viewbox Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                <Canvas Width="24" Height="24">
                                                    <Rectangle Canvas.Left="3" Canvas.Top="6" Width="18" Height="9" RadiusX="1.2" RadiusY="1.2" Stroke="#E5A93C" StrokeThickness="1.8" Fill="Transparent"/>
