"@

$reader = New-Object System.Xml.XmlNodeReader $xaml
$window = [Windows.Markup.XamlReader]::Load($reader)

$TitleBar    = $window.FindName("TitleBar")
$BtnMin      = $window.FindName("BtnMin")
$BtnClose    = $window.FindName("BtnClose")
$BgImage     = $window.FindName("BgImage")
$BgImage.Source = $script:BgBitmap


$AvatarImage        = $window.FindName("AvatarImage")
$AvatarImageBrush   = $window.FindName("AvatarImageBrush")
$AvatarFallbackIcon = $window.FindName("AvatarFallbackIcon")
if ($script:AvatarBitmap) {
    $AvatarImageBrush.ImageSource  = $script:AvatarBitmap
    $AvatarImage.Visibility        = "Visible"
    $AvatarFallbackIcon.Visibility = "Collapsed"
}

$TxtOs           = $window.FindName("TxtOs")
$TxtComputerName = $window.FindName("TxtComputerName")
$TxtUserName     = $window.FindName("TxtUserName")
$TxtCpu          = $window.FindName("TxtCpu")
$TxtRam          = $window.FindName("TxtRam")
$TxtGpu          = $window.FindName("TxtGpu")
$TxtNet          = $window.FindName("TxtNet")
$BtnRefreshSpecs = $window.FindName("BtnRefreshSpecs")

$Btn1 = $window.FindName("Btn1"); $Btn2 = $window.FindName("Btn2")
$Btn3 = $window.FindName("Btn3"); $Btn4 = $window.FindName("Btn4")
$Btn5 = $window.FindName("Btn5"); $Btn6 = $window.FindName("Btn6")
$Btn7 = $window.FindName("Btn7"); $Btn8 = $window.FindName("Btn8")
$Btn9 = $window.FindName("Btn9")
$Btn10 = $window.FindName("Btn10")
$Btn11 = $window.FindName("Btn11")

$LogPanel  = $window.FindName("LogPanel")
$LogScroll = $window.FindName("LogScroll")

$BtnTweakStandard = $window.FindName("BtnTweakStandard")
$BtnTweakAdvanced = $window.FindName("BtnTweakAdvanced")
$BtnSystemIni     = $window.FindName("BtnSystemIni")
$BtnResetTweaks   = $window.FindName("BtnResetTweaks")

$script:mainWindow = $window
$window.Add_Closed({ [BoostFPS.ConsoleWindow]::Show() })
$script:LogPanel   = $LogPanel
$script:LogScroll  = $LogScroll




$TitleBar.Add_MouseLeftButtonDown({ $script:mainWindow.DragMove() })
$BtnMin.Add_Click({ $script:mainWindow.WindowState = 'Minimized' })
$BtnClose.Add_Click({ $script:mainWindow.Close() })

function global:Add-LogLine {
    param([string]$Text, [string]$Color = "#E5A93C")
    $tb = New-Object System.Windows.Controls.TextBlock
    $tb.Text = $Text
    $tb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($Color)
    $tb.FontFamily = "Consolas"
    $tb.FontSize = 12
    $tb.Margin = "0,3,0,0"
    $tb.TextWrapping = "Wrap"
    $script:LogPanel.Children.Add($tb) | Out-Null
    $script:LogScroll.ScrollToEnd()
}

function Set-SpecFields {
    # Read the actual machine values instead of showing fixed example hardware.
    $TxtOs.Text = Get-SafeValue {
        $osInfo = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $caption = if ($osInfo.Caption) { $osInfo.Caption.Trim() } else { "Windows" }
        $version = if ($osInfo.Version) { " (v$($osInfo.Version))" } else { "" }
        "$caption$version"
    }

    $TxtComputerName.Text = Get-SafeValue { $env:COMPUTERNAME }
    $TxtUserName.Text     = Get-SafeValue { $env:USERNAME }

    $TxtCpu.Text = Get-SafeValue {
        $cpuInfo = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop |
            Sort-Object -Property DeviceID |
            Select-Object -First 1
        if ([string]::IsNullOrWhiteSpace([string]$cpuInfo.Name)) {
            throw "CPU name unavailable"
        }
        $cpuInfo.Name.Trim()
    }

    $TxtRam.Text = Get-SafeValue {
        $memoryInfo = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        if (-not $memoryInfo.TotalPhysicalMemory) {
            throw "Physical memory unavailable"
        }
        $ramGb = [math]::Round([double]$memoryInfo.TotalPhysicalMemory / 1GB, 1)
        "{0:N1} GB" -f $ramGb
    }

    $TxtGpu.Text = Get-SafeValue {
        $gpuNames = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop |
            Where-Object {
                $_.Name -and $_.Name -notmatch "Microsoft Basic Display Adapter"
            } |
            Select-Object -ExpandProperty Name)
        if ($gpuNames.Count -eq 0) {
            throw "GPU name unavailable"
        }
        ($gpuNames | Select-Object -Unique) -join " / "
    }

    $TxtNet.Text = Get-SafeValue {
        $adapterNames = @(Get-NetAdapter -ErrorAction Stop |
            Where-Object {
                $_.Status -eq "Up" -and $_.InterfaceDescription
            } |
            Select-Object -ExpandProperty InterfaceDescription)
        if ($adapterNames.Count -eq 0) {
            throw "No active adapter"
        }
        ($adapterNames | Select-Object -Unique) -join " / "
    } "No Adapter Found"
}
Set-SpecFields

function Write-LogTime {
    param([string]$Msg, [string]$Color = "#E5A93C")
    $timestamp = Get-Date -Format "HH:mm:ss"
    Add-LogLine -Text "[$timestamp] $Msg" -Color $Color
}

Write-LogTime "SAVAGE TOOL READY TO USE." "#33fd00"

$BtnRefreshSpecs.Add_Click({
    Write-LogTime "Manual spec refresh requested." "#8A8A94"
    Set-SpecFields
    Write-LogTime "Specs reloaded." "#00EBA0"
})

