$Btn2.Add_Click({
    Write-LogTime "NETWORK OPTIMIZATION working..." "#E5A93C"

    try {
        $nicClassPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
        $activeAdapter = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq "Up" } | Select-Object -First 1

        if ($activeAdapter) {
            $keyPath = Get-ChildItem -Path $nicClassPath -ErrorAction SilentlyContinue |
                Where-Object { (Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue).NetCfgInstanceId -eq $activeAdapter.InterfaceGuid } |
                Select-Object -First 1 -ExpandProperty PSPath

            if ($keyPath) {
                $props = Get-ItemProperty -Path $keyPath -ErrorAction SilentlyContinue

                $rxK = @("*ReceiveBuffers", "ReceiveBuffers") | Where-Object { $props.PSObject.Properties.Name -contains $_ } | Select-Object -First 1
                $txK = @("*TransmitBuffers", "TransmitBuffers") | Where-Object { $props.PSObject.Properties.Name -contains $_ } | Select-Object -First 1
                $imK = @("*InterruptModeration", "InterruptModeration") | Where-Object { $props.PSObject.Properties.Name -contains $_ } | Select-Object -First 1
            } else {
                Write-LogTime "» Could not locate adapter registry key" "#FF915C"
            }
        } else {
            Write-LogTime "» No active network adapter found" "#FF915C"
        }
